    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Edge bars trigger inward lines in the marker color; isolated markers become 4
    # and extend in a straight line toward the nearest aligned edge bar.
    bg=max({v for row in grid for v in row}, key=lambda v:sum(row.count(v) for row in grid))
    marks=[(r,c,v) for r in range(h) for c,v in enumerate(grid[r]) if v!=bg and (r not in (0,h-1) and c not in (0,w-1))]
    markcolors={v for _,_,v in marks}
    for r,c,v in marks:
        out[r][c]=4
        # Find nearest edge bar along row/column, project marker color to it.
        candidates=[]
        for rr in range(h):
            for cc in range(w):
                if (rr in (0,h-1) or cc in (0,w-1)) and grid[rr][cc]!=bg:
                    if rr==r: candidates.append((abs(cc-c),rr,cc))
                    if cc==c: candidates.append((abs(rr-r),rr,cc))
        if candidates:
            _,rr,cc=min(candidates)
            dr=0 if rr==r else (1 if rr>r else -1)
            dc=0 if cc==c else (1 if cc>c else -1)
            y,x=r+dr,c+dc
            while (y,x)!=(rr,cc):
                if grid[y][x]==bg: out[y][x]=v
                y+=dr; x+=dc
    # Rays from edge bars inward, limited to tracks marked by seed columns/rows.
    for r,c,v in marks:
        for er,ec in ((0,c),(h-1,c),(r,0),(r,w-1)):
            if grid[er][ec]!=bg:
                dr=0 if er==r else (1 if er>r else -1)
                dc=0 if ec==c else (1 if ec>c else -1)
                y,x=er+dr,ec+dc
