def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # The edge pattern is copied inward as vertical projections: top-right bar projects
    # its 1-columns down; bottom-left bar projects its 1-columns up. Dots become 4.
    for c in range(w):
        if grid[0][c]==1:
            for r in range(1,h):
                if grid[r][c]==9: out[r][c]=1
        if grid[h-1][c]==1:
            for r in range(h-2,-1,-1):
                if grid[r][c]==9: out[r][c]=1
    # Interior 3 markers are changed to 4 and project their color toward nearest horizontal edge.
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==3:
                out[r][c]=4
                # Extend horizontally only to nearest existing bar at either edge.
                if c< w//2:
                    for x in range(c-1,-1,-1):
                        if grid[r][x]==1: break
                        if grid[r][x]==9: out[r][x]=3
                else:
                    for x in range(c+1,w):
                        if grid[r][x]==1: break
                        if grid[r][x]==9: out[r][x]=3
    return out
