def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Demonstrations show isolated colored cells (not the background or edge bars)
    # become 4 and paint their row/column toward associated boundary bars in the
    # marker's original color. Different instances can vary colors/axes.
    from collections import Counter
    counts=Counter(v for row in grid for v in row)
    bg=counts.most_common(1)[0][0]
    edges={(r,c) for r in range(h) for c in range(w)
           if (r==0 or r==h-1 or c==0 or c==w-1) and grid[r][c]!=bg}
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v==bg or (r,c) in edges:
                continue
            out[r][c]=4
            # extend toward the closest non-background boundary marker on row or column
            targets=[]
            for er,ec in edges:
                if er==r: targets.append((abs(ec-c),er,ec))
                if ec==c: targets.append((abs(er-r),er,ec))
            if targets:
                _,er,ec=min(targets)
                if er==r:
                    step=1 if ec>c else -1
                    for x in range(c+step,ec,step):
                        if grid[r][x]==bg: out[r][x]=v
                else:
                    step=1 if er>r else -1
                    for y in range(r+step,er,step):
                        if grid[y][c]==bg: out[y][c]=v
    return out
